<?php
/** Investor/subaccount VPS checkout. No VPS IPs or provisioning credentials are queried. */
require_once __DIR__ . '/vps_purchase_guard.php';
$type='account';$programmeId=0;$activeProgramme=null;
if($isPurchaseAjax){
    try{
        if(!purchaseCheckCsrf())purchaseJson(['success'=>false,'message'=>'Security token expired. Reload and try again.'],419);
        $action=(string)($_POST['action'] ?? '');
        if($action==='begin_purchase'){
            $planId=(int)($_POST['vps_id'] ?? 0);if($planId<=0)throw new RuntimeException('Choose a valid VPS plan.');
            $requestId=purchaseBeginRequest($purchasePdo,$type,$purchaseUser,$purchaseSubId,$planId);
            purchaseJson(['success'=>true,'request_id'=>$requestId,'redirect'=>'investorapp.php?tab=purchase_vps&request_id='.$requestId]);
        }
        if($action==='mark_payment_made'){
            $requestId=(int)($_POST['request_id'] ?? 0);$method=strtoupper(trim((string)($_POST['payment_method'] ?? '')));$reference=trim((string)($_POST['payment_reference'] ?? ''));
            purchaseMarkPayment($purchasePdo,$requestId,$type,$purchaseUserId,$purchaseSubId,0,$method,$reference,$purchaseServerAccount);
            purchaseJson(['success'=>true,'message'=>'Payment submitted. Your VPS will be registered after the server confirms the payment.']);
        }
        purchaseJson(['success'=>false,'message'=>'Unknown purchase action.'],400);
    }catch(Throwable $e){purchaseJson(['success'=>false,'message'=>$e->getMessage()],400);}
}
$requestId=(int)($_GET['request_id'] ?? 0);$purchase=null;$plan=null;
if($requestId>0){
    $q=$purchasePdo->prepare("SELECT r.id,r.vps_id,r.request_name,r.request_email,r.payment_status,r.request_status,r.amount,r.currency,r.payment_method,r.payment_network,r.payment_reference,r.payment_made_at,r.allocation_message,v.product_name,v.provider_name,v.plan_name,v.plan_description,v.cpu_type,v.vcpu_count,v.ram_gb,v.storage_type,v.storage_gb,v.network_port_speed_mbps,v.data_transfer,v.server_location,v.operating_system,v.billing_period,v.subscription_duration_days FROM server_vps_purchase_requests r INNER JOIN server_available_vps v ON v.id=r.vps_id WHERE r.id=? AND r.request_type='account' AND r.user_id=? AND r.sub_account_id=? LIMIT 1");
    $q->execute([$requestId,$purchaseUserId,$purchaseSubId]);$purchase=$q->fetch(PDO::FETCH_ASSOC) ?: null;
}
$methods=[];
foreach(['BTC'=>['btc_address','Bitcoin'],'ETH'=>['eth_address',(string)($purchaseServerAccount['eth_network'] ?? '')],'USDT'=>['usdt_address',(string)($purchaseServerAccount['usdt_network'] ?? '')]] as $key=>$m){$address=trim((string)($purchaseServerAccount[$m[0]] ?? ''));if($address!=='')$methods[$key]=['address'=>$address,'network'=>$m[1]];}
$csrf=$purchaseCsrf;
function accountPurchaseH($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchase VPS</title><style>
*{box-sizing:border-box}body{margin:0;padding:18px;background:#f4f7fb;color:#19283a;font:14px/1.55 Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:900px;margin:0 auto}.back{display:inline-block;margin-bottom:15px;color:#1769aa;text-decoration:none;font-weight:700}.card{background:#fff;border:1px solid #e2e9f1;border-radius:16px;padding:22px;margin-bottom:15px}.card h1{font-size:23px;margin:0 0 5px}.muted{color:#718096}.specs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:18px}.spec{background:#f7f9fc;padding:12px;border-radius:10px}.spec span{display:block;color:#7a8797;font-size:11px}.spec b{display:block;margin-top:2px}.price{font-size:24px;color:#164f7d;font-weight:850}.field{display:grid;gap:6px;margin:14px 0}.field label{font-weight:700;font-size:12px}.field input,.field select{padding:11px 12px;border:1px solid #dce5ee;border-radius:9px;font:inherit;width:100%}.btn{border:0;border-radius:9px;padding:11px 15px;background:#1769aa;color:#fff;font:inherit;font-weight:750;cursor:pointer}.btn:disabled{opacity:.55}.notice{padding:13px 15px;background:#eaf5ff;color:#1a5687;border-radius:10px;margin:12px 0}.notice.good{background:#e6f7ed;color:#176a42}.notice.bad{background:#fff0f0;color:#a83232}.address{padding:12px;border:1px dashed #b9cbdc;background:#f7fafc;border-radius:9px;overflow-wrap:anywhere}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.status{display:inline-block;padding:5px 9px;border-radius:99px;background:#edf2f7;font-size:12px;font-weight:750}.status.payment-made{background:#e8f2ff;color:#185c9b}.status.payment-confirmed{background:#e5f7ee;color:#146b44}.status.payment-failed{background:#ffebeb;color:#a83232}@media(max-width:600px){body{padding:12px}.specs{grid-template-columns:repeat(2,minmax(0,1fr))}.card{padding:17px}}
</style></head><body><main class="wrap"><a class="back" href="investorapp.php?tab=vps" target="_top">← Back to VPS Hub</a>
<?php if(!$purchase): ?><section class="card"><h1>VPS Checkout</h1><p class="muted">No active checkout was found for this subaccount. Return to the VPS Hub and select a published plan to begin.</p></section>
<?php else: ?><section class="card"><h1>Purchase VPS</h1><p class="muted">Request #<?= (int)$purchase['id'] ?> · Subaccount #<?= (int)$purchaseSubId ?></p><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center"><div><h2 style="font-size:18px;margin:12px 0 4px"><?= accountPurchaseH($purchase['product_name']) ?> · <?= accountPurchaseH($purchase['plan_name']) ?></h2><p class="muted" style="margin:0"><?= accountPurchaseH($purchase['plan_description']) ?></p></div><div class="price"><?= accountPurchaseH($purchase['currency']) ?> <?= number_format((float)$purchase['amount'],2) ?><div class="muted" style="font-size:11px;font-weight:500">First payment including setup fee</div></div></div><div class="specs"><div class="spec"><span>CPU</span><b><?= (int)$purchase['vcpu_count'] ?> vCPU <?= accountPurchaseH($purchase['cpu_type']) ?></b></div><div class="spec"><span>Memory</span><b><?= accountPurchaseH($purchase['ram_gb']) ?> GB RAM</b></div><div class="spec"><span>Storage</span><b><?= accountPurchaseH($purchase['storage_gb']) ?> GB <?= accountPurchaseH($purchase['storage_type']) ?></b></div><div class="spec"><span>Location</span><b><?= accountPurchaseH($purchase['server_location']) ?></b></div><div class="spec"><span>Network / transfer</span><b><?= accountPurchaseH($purchase['network_port_speed_mbps'] ? $purchase['network_port_speed_mbps'].' Mbps' : 'Not stated') ?> · <?= accountPurchaseH($purchase['data_transfer'] ?: 'Not stated') ?></b></div><div class="spec"><span>Term</span><b><?= (int)$purchase['subscription_duration_days'] ?> days · <?= accountPurchaseH($purchase['billing_period']) ?></b></div></div></section>
<section class="card"><h2 style="margin:0 0 8px;font-size:17px">Payment status</h2><p><span class="status <?= accountPurchaseH($purchase['payment_status']) ?>"><?= accountPurchaseH(str_replace('-',' ',ucwords($purchase['payment_status'],'-'))) ?></span></p>
<?php if($purchase['payment_status']==='awaiting_payment'): ?><p class="muted">Choose one of the configured payment methods below. Send the exact amount, then submit the transaction reference. Your VPS is registered only after administrator confirmation.</p>
<?php if(!$methods): ?><div class="notice bad">No payment methods are currently configured. Contact support before sending funds.</div><?php else: ?><div class="field"><label for="paymentMethod">Payment method</label><select id="paymentMethod"><option value="">Choose payment method</option><?php foreach($methods as $key=>$m): ?><option value="<?= accountPurchaseH($key) ?>"><?= accountPurchaseH($key) ?> · <?= accountPurchaseH($m['network']) ?></option><?php endforeach; ?></select></div><div id="paymentDetails" hidden><div class="field"><label>Send payment to</label><div class="address" id="paymentAddress"></div><div class="row"><button class="btn" type="button" onclick="copyAddress()">Copy address</button><span class="muted" id="paymentNetwork"></span></div></div><div class="field"><label for="paymentReference">Transaction reference / hash</label><input id="paymentReference" maxlength="190" placeholder="Enter the payment transaction reference"></div><button class="btn" type="button" onclick="markPaymentMade()">I have made this payment</button></div><?php endif; ?>
<?php elseif($purchase['payment_status']==='payment-made'): ?><div class="notice">Your payment has been submitted and is awaiting server confirmation. The VPS will be registered after the administrator confirms the transaction.</div><p class="muted">Reference: <?= accountPurchaseH($purchase['payment_reference'] ?: 'Not supplied') ?> · Submitted: <?= accountPurchaseH($purchase['payment_made_at'] ?: '—') ?></p>
<?php elseif($purchase['payment_status']==='payment-confirmed'): ?><div class="notice good">Payment confirmed. Your subaccount has been registered to the published VPS plan.</div>
<?php else: ?><div class="notice bad">The payment was marked as failed. Please contact support or choose another published VPS plan for a new request.</div><?php endif; ?>
</section><?php endif; ?></main>
<script>
const csrf=<?= json_encode($csrf) ?>,requestId=<?= (int)$requestId ?>,methods=<?= json_encode($methods,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const methodSelect=document.getElementById('paymentMethod');methodSelect?.addEventListener('change',function(){const m=methods[this.value],box=document.getElementById('paymentDetails');box.hidden=!m;if(m){document.getElementById('paymentAddress').textContent=m.address;document.getElementById('paymentNetwork').textContent=m.network||''}});
function copyAddress(){const t=document.getElementById('paymentAddress')?.textContent||'';if(navigator.clipboard)navigator.clipboard.writeText(t).then(()=>alert('Payment address copied.'));else alert(t)}
async function post(action,data){const body=new URLSearchParams({action,csrf_token:csrf,...data});const r=await fetch('purchaseaccountvps.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-Requested-With':'XMLHttpRequest'},body});return r.json()}
async function markPaymentMade(){const method=methodSelect?.value||'',reference=document.getElementById('paymentReference')?.value.trim()||'';if(!method){alert('Choose a payment method.');return}try{const d=await post('mark_payment_made',{request_id:String(requestId),payment_method:method,payment_reference:reference});if(!d.success)throw new Error(d.message);alert(d.message);location.reload()}catch(e){alert(e.message)}}
</script></body></html>
